app.use('/admin', (req, res, next) => {
  if (!req.user || !req.user.isAdmin) {
    return res.status(403).send(`
      <h1>Access Denied</h1>
      <p>You are not authorized to view this page.</p>
      <a href="/">Return Home</a>
    `);
